import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params
    const body = await request.json()
    const { name, accountInfo, isActive } = body

    const existing = await db.paymentMethod.findUnique({ where: { id } })
    if (!existing) {
      return NextResponse.json({ error: 'طريقة الدفع غير موجودة' }, { status: 404 })
    }

    const payment = await db.paymentMethod.update({
      where: { id },
      data: {
        ...(name !== undefined && { name }),
        ...(accountInfo !== undefined && { accountInfo }),
        ...(isActive !== undefined && { isActive }),
      },
    })

    return NextResponse.json(payment)
  } catch (error) {
    return NextResponse.json({ error: 'حدث خطأ في الخادم' }, { status: 500 })
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params

    const existing = await db.paymentMethod.findUnique({ where: { id } })
    if (!existing) {
      return NextResponse.json({ error: 'طريقة الدفع غير موجودة' }, { status: 404 })
    }

    await db.paymentMethod.delete({ where: { id } })
    return NextResponse.json({ message: 'تم حذف طريقة الدفع بنجاح' })
  } catch (error) {
    return NextResponse.json({ error: 'حدث خطأ في الخادم' }, { status: 500 })
  }
}
